/* ---------- תבניות לטקסט עם שמות ונתונים ---------- */
const F = (fr, ar) => ({ fr: fr, ar: ar });
const list = (s, t) => s.split(/, ?/).map(x => t(x.trim())).join(", ");
const RV = { "שלח לאישור": F("a envoyé pour validation", "أرسل للموافقة"), "אישר": F("a validé", "وافق على"), "החזיר לתיקון": F("a renvoyé pour correction", "أعاد للتصحيح") };
